function overview(){const f=(filter==='b2b'?.248:filter==='b2c'?.752:1)*(period==='quarter'?2.84:1);const completed=state.controls.filter(c=>c.status==='已留证').length;const channels=[['a','Amazon','全球电商平台',749.9,58.3,'b2c'],['S','独立站','品牌直营渠道',217.5,16.9,'b2c'],['B','TOB 分销','企业客户与经销商',319,24.8,'b2b']].filter(x=>filter==='all'||filter===x[5]);const total=channels.reduce((s,c)=>s+c[3],0);const p=product('BT100');const incoming=state.purchaseOrders.filter(o=>o.sku===p.sku&&o.status!=='已收货').reduce((s,o)=>s+o.qty,0);const suggestion=Math.max(0,p.daily*30-p.stock-incoming);const financePending=state.orders.filter(o=>o.status==='待结算'&&o.variance>0);let graph=chart();if(period==='quarter')graph=graph.replace('09/01','07/01').replace('09/05','07/15').replace('09/10','08/01').replace('09/15','08/15').replace('09/20','09/01');return head('经营总览','EXECUTIVE OVERVIEW','全链路经营，尽在掌握。',btn(icon('download')+'导出经营快照','export')+btn(icon('play')+'开始演示','guide','primary'))+`<div class="filterbar"><div class="segmented">${[['all','全部业务'],['b2c','TOC 零售'],['b2b','TOB 分销']].map(x=>`<button data-filter="${x[0]}" class="${filter===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><select id="period" class="select" aria-label="统计周期"><option value="month">2026 年 9 月 · 月度</option><option value="quarter">2026 年 Q3 · 季度</option></select><span class="last">截至 2026.09.26 · 模拟经营快照</span></div>${kpis([['营业收入',fmt(+(1286.4*f).toFixed(1)),'万元',`<span class="positive">↗ ${period==='quarter'?'21.3':'18.6'}%</span> 较${period==='quarter'?'上季':'上月'}同期`,'finance'],['经营毛利率',filter==='b2b'?'36.2':filter==='b2c'?'31.7':'32.8','%','<span class="positive">↗ 2.4 pp</span> 较上期同期'],['库存周转天数',filter==='b2b'?'39.8':'46.2','天','<span class="positive">↘ 5.3 天</span> 较上期同期','supply'],['演示控制完成度',(completed/6*100).toFixed(1),'%',`<span class="${completed===6?'positive':'warning'}">${6-completed} 项待闭环</span> 共 6 项演示控制`,'shield']])}<div class="overview-grid"><section class="panel"><div class="panel-head"><h2>收入与增长</h2><div class="legend"><span><i></i>本期收入</span><span><i style="background:#cbcadd"></i>上期收入</span></div></div>${graph}<div class="chart-note"><span>统一人民币 · 扣除退款 · 不含税</span><span>模拟趋势 · ${period==='quarter'?'季度':'月度'}</span></div><div class="insight">${icon('spark')}<span>${filter==='b2b'?'分销业务重点关注账期与交付承诺。':filter==='b2c'?'TOC 收入由平台零售与品牌独立站共同构成。':'TOB 渠道占比 24.8%，重点打通双业务数据与财务口径。'}</span></div></section><section class="panel"><div class="panel-head"><h2>渠道收入贡献</h2><button class="text-btn" data-route="orders">查看渠道 ${icon('arrow')}</button></div>${channels.map((x,i)=>`<div class="channel-row"><div class="channel-icon">${x[0]}</div><div><strong>${x[1]}</strong><small>${x[2]}</small><div class="bar"><span style="width:${x[3]/total*100}%;background:${['#827ad9','#aaa2e7','#bcc3df'][i]}"></span></div></div><div class="amount">¥${fmt(+(x[3]*(period==='quarter'?2.84:1)).toFixed(1))}<small>${(x[3]/total*100).toFixed(1)}% · 万元</small></div></div>`).join('')}<div class="insight">${icon('link')}<span>统一订单 · 统一商品 · 统一财务口径</span></div></section></div><div class="lower-grid"><section class="panel"><div class="panel-head"><h2>供应链关注</h2><button class="text-btn" data-route="supply">供应链工作台 ${icon('arrow')}</button></div><div class="table-wrap"><table><thead><tr><th>产品 / SKU</th><th>可用库存</th><th>预计覆盖</th><th>状态</th></tr></thead><tbody>${state.products.filter(x=>x.sku!=='PHX-L3').map(x=>`<tr><td><strong>${x.name}</strong><small>${x.sku} · ${x.warehouse}</small></td><td>${fmt(x.stock)} 件</td><td>${Math.floor(x.stock/x.daily)} 天</td><td>${badge(x.stock<x.safety?'待补货':x.stock/x.daily>60?'关注库龄':'库存健康',x.stock<x.safety?'warn':x.stock/x.daily>60?'purple':'good')}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>今日待办</h2><small>按业务影响排序 · 随操作更新</small></div>${[['finance','finance',financePending.length?'结算单存在费用差异':'结算费用差异已闭环',financePending.length?`${financePending.length} 笔待核对 · 差异 ${money(financePending.reduce((s,o)=>s+o.variance,0))}`:'查看已生成凭证与最新结算记录','核对'],['supply','supply',p.stock<p.safety?'美国仓库存低于安全水位':'美国仓安全库存已满足',`BT100 · ${suggestion?'建议补货 '+suggestion+' 件':'无需新增采购'}`,'查看'],['shield','compliance',completed<6?'关键控制待完成复核':'演示控制全部完成',`${6-completed} 项待闭环 · 查看复核与证据记录`,'审查']].map((x,i)=>`<div class="task"><div class="task-symbol ${i===1?'purple':i===2?'red':''}">${icon(x[0])}</div><div class="task-content"><strong>${x[2]}</strong><p>${x[3]}</p></div><button class="text-btn" data-route="${x[1]}">${x[4]} →</button></div>`).join('')}</section></div><div class="notice tabs-spacer">经营趋势为模拟汇总快照；订单、库存、凭证及审计台账随演示操作实时变化。${state.journals.length?`已完成 ${state.journals.length} 笔入账，到账 ${money(state.journals.reduce((s,j)=>s+net(state.orders.find(o=>o.id===j.order)),0))}。`:''}</div>`+footer()}
